-- KodFormula database: clean UTF-8/JSON-safe dump
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS score_events, course_assignments, submissions, step_progress, enrollments, steps, step_types, modules, courses, users, app_settings;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, login VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(120) NOT NULL, role ENUM('student','curator','admin') NOT NULL, grade TINYINT UNSIGNED NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, last_login_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE app_settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE courses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, classes_label VARCHAR(50) NOT NULL, tool VARCHAR(255) NOT NULL, duration_label VARCHAR(120), goal TEXT NOT NULL, status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', version INT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE modules (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, course_id INT UNSIGNED NOT NULL, code VARCHAR(30) NOT NULL, title VARCHAR(255) NOT NULL, position INT NOT NULL, UNIQUE KEY uq_module(course_id,code), CONSTRAINT fk_module_course FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE step_types (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, title VARCHAR(120) NOT NULL, grading ENUM('read','auto','manual','hybrid') NOT NULL, icon_code VARCHAR(20) NOT NULL DEFAULT 'T', schema_json JSON NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE steps (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, module_id INT UNSIGNED NOT NULL, code VARCHAR(30) NOT NULL, title VARCHAR(255) NOT NULL, step_type_id INT UNSIGNED NOT NULL, position INT NOT NULL, content_json JSON NOT NULL, validation_json JSON NOT NULL, teacher_only_json JSON NOT NULL, UNIQUE KEY uq_step(module_id,code), CONSTRAINT fk_step_module FOREIGN KEY(module_id) REFERENCES modules(id) ON DELETE CASCADE, CONSTRAINT fk_step_type FOREIGN KEY(step_type_id) REFERENCES step_types(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE enrollments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, course_id INT UNSIGNED NOT NULL, student_id INT UNSIGNED NOT NULL, curator_id INT UNSIGNED NULL, enrolled_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_enrollment(course_id,student_id), FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(curator_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE step_progress (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id INT UNSIGNED NOT NULL, step_id INT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'idle', opened_at DATETIME NULL, completed_at DATETIME NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_progress(student_id,step_id), KEY idx_progress_student(student_id,status), FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(step_id) REFERENCES steps(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, step_id INT UNSIGNED NOT NULL, student_id INT UNSIGNED NOT NULL, status ENUM('in_progress','review','accepted','returned','failed') NOT NULL DEFAULT 'in_progress', payload_json JSON NOT NULL, score DECIMAL(8,2) NULL, curator_comment TEXT NULL, submitted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at DATETIME NULL, reviewer_id INT UNSIGNED NULL, KEY idx_queue(status,submitted_at), FOREIGN KEY(step_id) REFERENCES steps(id) ON DELETE CASCADE, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(reviewer_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE course_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, course_id INT UNSIGNED NOT NULL, student_id INT UNSIGNED NOT NULL, curator_id INT UNSIGNED NULL, assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_assignment(course_id,student_id), FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(curator_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE score_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id INT UNSIGNED NOT NULL, course_id INT UNSIGNED NULL, source VARCHAR(40) NOT NULL, points DECIMAL(8,2) NOT NULL, reason TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

